"""Hand-built stroke icons for the one-canvas whiteboard look (free, no assets).
Each icon is drawn in a 100x100 box (y down): {'strokes':[(colour,[(x,y),...]),...], 'fills':[(colour,[(x,y),...]),...]}.
Colours: k ink, r red, g green, b blue, y yellow, o orange. Fills are flat colour, pasted when the pen finishes.
"""
import math

def circ(cx, cy, r, n=30, a0=0, a1=360):
    return [(cx + r * math.cos(math.radians(a0 + (a1 - a0) * i / n)), cy + r * math.sin(math.radians(a0 + (a1 - a0) * i / n))) for i in range(n + 1)]

def ell(cx, cy, rx, ry, n=30):
    return [(cx + rx * math.cos(2 * math.pi * i / n), cy + ry * math.sin(2 * math.pi * i / n)) for i in range(n + 1)]

def rect(x, y, w, h):
    return [(x, y), (x + w, y), (x + w, y + h), (x, y + h), (x, y)]

def bez(p0, p1, p2, p3, n=18):
    out = []
    for i in range(n + 1):
        t = i / n; u = 1 - t
        out.append((u**3 * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t**3 * p3[0],
                    u**3 * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t**3 * p3[1]))
    return out

def dollar(cx=50, cy=50, s=1.0):
    pts = bez((cx + 14 * s, cy - 14 * s), (cx + 10 * s, cy - 26 * s), (cx - 16 * s, cy - 26 * s), (cx - 14 * s, cy - 8 * s))
    pts += bez((cx - 14 * s, cy - 8 * s), (cx - 12 * s, cy + 4 * s), (cx + 14 * s, cy + 2 * s), (cx + 14 * s, cy + 14 * s))[1:]
    pts += bez((cx + 14 * s, cy + 14 * s), (cx + 14 * s, cy + 28 * s), (cx - 10 * s, cy + 28 * s), (cx - 14 * s, cy + 16 * s))[1:]
    return [pts, [(cx, cy - 32 * s), (cx, cy + 32 * s)]]

LT = {'g': (178, 222, 178), 'y': (252, 220, 90), 'b': (190, 222, 244), 'o': (244, 190, 130), 'r': (240, 150, 140), 'n': (206, 214, 150), 'w': (236, 236, 236), 'br': (200, 150, 100)}

def I(strokes, fills=None):
    return {'strokes': strokes, 'fills': fills or []}

